export const GLOSSARY = [...BASE, ...MORE, ...MORE2, ...MORE3];

const byKey = new Map(GLOSSARY.map(g => [g.key, g]));
const norm = s =>
  String(s || '')
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
const byName = new Map();
for (const g of GLOSSARY) for (const name of g.term) byName.set(norm(name.replace(/\s*\(.*\)/, '')), g);

/** Finds a term by key or by its name in either language. */
export const findTerm = key => byKey.get(key) || byKey.get(norm(key)) || byName.get(norm(key)) || null;
